html:
{% set pl = doc.price_list or {} %}
{% set matrix = pl.matrix or [] %}
{% set kit_only = pl.kit_only or [] %}
{% set coverage = doc.kit_coverage %}

<style>
  body, .xf-print { font-family: Arial, Helvetica, sans-serif; font-size: 10px; color: #000; }
  .xf-hdr { margin-bottom: 10px; padding-bottom: 8px; border-bottom: 2px solid #174096; }
  .xf-hdr td { border: none !important; padding: 0; vertical-align: top; }
  .xf-logo { height: 32px; vertical-align: middle; margin-right: 8px; }
  .xf-title { font-size: 16px; font-weight: bold; color: #174096; }
  .xf-sub { font-size: 9px; color: #444; }
  .xf-gst { font-size: 10px; font-weight: bold; margin: 8px 0; padding: 6px 8px; border: 1px solid #999; background: #f5f5f5; }
  table.xf-tbl {
    width: 100%;
    border-collapse: collapse;
    font-size: 9px;
  }
  table.xf-tbl th, table.xf-tbl td {
    border: 1px solid #000;
    padding: 4px 5px;
  }
  table.xf-tbl th {
    background: #eee;
    font-weight: bold;
    text-align: center;
  }
  table.xf-tbl td.sys { text-align: left; }
  table.xf-tbl td.num { text-align: right; }
  table.xf-tbl td.tot { text-align: right; font-weight: bold; }
  .xf-foot { margin-top: 12px; font-size: 8px; color: #666; }
</style>

<div class="xf-print">
<table class="xf-hdr" width="100%" cellpadding="0" cellspacing="0">
  <tr>
    <td width="60%">
      <img class="xf-logo" src="data:image/png;base64," alt=""/>
      <span class="xf-title">Xfloor</span>
      <div class="xf-sub">Kit Price List (₹/sqft) + GST</div>
    </td>
    <td width="40%" align="right">
      <div class="xf-sub">Generated: {{ frappe.utils.formatdate(frappe.utils.nowdate(), "dd MMM yyyy") }}</div>
      {% if doc.rates_effective_date %}<div class="xf-sub">Rates: {{ frappe.utils.formatdate(doc.rates_effective_date, "dd MMM yyyy") }}</div>{% endif %}
      {% if coverage and coverage.coverage_effective_date %}<div class="xf-sub">Coverage: {{ frappe.utils.formatdate(coverage.coverage_effective_date, "dd MMM yyyy") }}</div>{% endif %}
      <div class="xf-sub">App cost: ₹{{ pl.applicator_rate or 10 }}/sqft</div>
    </td>
  </tr>
</table>

<div class="xf-gst">All prices exclusive of GST (+ GST)</div>

<table class="xf-tbl" cellpadding="0" cellspacing="0">
  <thead>
    <tr>
      <th width="32%" align="left">System</th>
      <th width="11%">Primer</th>
      <th width="11%">Screed</th>
      <th width="11%">Top Coat</th>
      <th width="11%">App Cost</th>
      <th width="11%">Total</th>
    </tr>
    <tr>
      <th></th>
      <th>₹/sqft</th>
      <th>₹/sqft</th>
      <th>₹/sqft</th>
      <th>₹/sqft</th>
      <th>₹/sqft</th>
    </tr>
  </thead>
  <tbody>
  {% for row in matrix %}
    <tr>
      <td class="sys">{{ row.label }}</td>
      <td class="num">{{ row.primer_display }}</td>
      <td class="num">{{ row.screed_display }}</td>
      <td class="num">{{ row.top_coat_display }}</td>
      <td class="num">{{ row.application_display }}</td>
      <td class="tot">{{ row.total_display }}</td>
    </tr>
  {% endfor %}
  </tbody>
</table>

{% if kit_only %}
<p style="margin:12px 0 4px;font-weight:bold;font-size:10px">Coving &amp; Hi-build (₹/kit)</p>
<table class="xf-tbl" width="50%" cellpadding="0" cellspacing="0">
  <thead><tr><th>Component</th><th>₹/kit</th><th>Note</th></tr></thead>
  <tbody>
  {% for row in kit_only %}
    <tr>
      <td>{{ row.component }}</td>
      <td class="num">{{ frappe.utils.fmt_money(row.rate_per_kit or 0, currency="INR") }}</td>
      <td>{{ row.note or "" }}</td>
    </tr>
  {% endfor %}
  </tbody>
</table>
{% endif %}

<div class="xf-foot">Xfloor Project Manager — Kit Rates Price List</div>
</div>
